head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL00012";

// TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — certiYn, ahthSvrType, ahthDdtm, ahthKeyNo, messageStr

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil00012.onpageload' });
    }
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        if ((String(((dma_pageContext.get("certiYn") ?? "")) == null ? '' : ((dma_pageContext.get("certiYn") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("certiYn") ?? "")) == null ? '' : ((dma_pageContext.get("certiYn") ?? "")))) === 'Y') {
            parent.fn_submit((String(((dma_pageContext.get("ahthSvrType") ?? "")) == null ? '' : ((dma_pageContext.get("ahthSvrType") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("ahthSvrType") ?? "")) == null ? '' : ((dma_pageContext.get("ahthSvrType") ?? "")))), (String(((dma_pageContext.get("ahthDdtm") ?? "")) == null ? '' : ((dma_pageContext.get("ahthDdtm") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("ahthDdtm") ?? "")) == null ? '' : ((dma_pageContext.get("ahthDdtm") ?? "")))), (String(((dma_pageContext.get("ahthKeyNo") ?? "")) == null ? '' : ((dma_pageContext.get("ahthKeyNo") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("ahthKeyNo") ?? "")) == null ? '' : ((dma_pageContext.get("ahthKeyNo") ?? "")))));
        } else {
            parent.certificationMessage((String(((dma_pageContext.get("messageStr") ?? "")) == null ? '' : ((dma_pageContext.get("messageStr") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("messageStr") ?? "")) == null ? '' : ((dma_pageContext.get("messageStr") ?? "")))));
        }

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil00012.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };
